SELECT count(*) INTO n_v3 FROM provocations
 WHERE gate_verdict->>'gate_version' = '3';
IF n_v3 = 0 THEN
  RAISE EXCEPTION 'REFUSING TO APPLY: no provocation has been gated by gate_version 3, so the binary carrying the fatal readability rail is not live yet.';
END IF;

EXECUTE 'SELECT count(*) FROM (' || pq || ') s' INTO c;
IF inv < 14 AND c <> 1 THEN
  RAISE EXCEPTION 'inventory is % (short of 14) but the pre_query returned % rows', inv, c;
END IF;
IF inv >= 14 AND c <> 0 THEN
  RAISE EXCEPTION 'inventory is % (>= 14) but the pre_query returned % rows', inv, c;
END IF;

